import{_ as i,c as l,o,ae as a}from"./chunks/framework.DMK_uHmU.js";const p=JSON.parse('{"title":"AI Model Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Settings/large-language-models.md","filePath":"Administration/AI-Management/Settings/large-language-models.md"}'),t={name:"Administration/AI-Management/Settings/large-language-models.md"};function n(s,e,r,d,c,u){return o(),l("div",null,e[0]||(e[0]=[a('<h1 id="ai-model-configuration-guide" tabindex="-1">AI Model Configuration Guide <a class="header-anchor" href="#ai-model-configuration-guide" aria-label="Permalink to &quot;AI Model Configuration Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#ai-model-configuration-guide">AI Model Configuration Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-ai-model-configuration">Accessing AI Model Configuration</a></li><li><a href="#ai-models-overview">AI Models Overview</a></li><li><a href="#model-selection-interface">Model Selection Interface</a><ul><li><a href="#model-cards">Model Cards</a></li><li><a href="#model-details">Model Details</a></li><li><a href="#enabling-models">Enabling Models</a></li></ul></li><li><a href="#understanding-model-information">Understanding Model Information</a><ul><li><a href="#provider-information">Provider Information</a></li><li><a href="#model-specifications">Model Specifications</a></li><li><a href="#cost-information">Cost Information</a></li><li><a href="#status-indicators">Status Indicators</a></li><li><a href="#categories">Categories</a></li></ul></li><li><a href="#managing-model-visibility">Managing Model Visibility</a><ul><li><a href="#expandcollapse-features">Expand/Collapse Features</a></li></ul></li><li><a href="#model-selection-strategy">Model Selection Strategy</a><ul><li><a href="#use-case-considerations">Use Case Considerations</a></li><li><a href="#cost-management">Cost Management</a></li><li><a href="#performance-requirements">Performance Requirements</a></li></ul></li><li><a href="#best-practices">Best Practices</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI Model Configuration interface allows administrators to select which Large Language Models (LLMs) are available for use within the platform. This setting determines which AI models users can select when creating Blueprints and configuring AI assistants. By controlling model availability, administrators can balance capabilities, costs, and performance based on organizational needs.</p><h2 id="accessing-ai-model-configuration" tabindex="-1">Accessing AI Model Configuration <a class="header-anchor" href="#accessing-ai-model-configuration" aria-label="Permalink to &quot;Accessing AI Model Configuration&quot;">​</a></h2><p>The AI Model Configuration is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>This interface is typically found in the system settings under AI Settings or Advanced Configuration sections.</p><h2 id="ai-models-overview" tabindex="-1">AI Models Overview <a class="header-anchor" href="#ai-models-overview" aria-label="Permalink to &quot;AI Models Overview&quot;">​</a></h2><p>Large Language Models (LLMs) are the foundation of AI capabilities in the platform. Different models offer varying capabilities, costs, and performance characteristics:</p><ol><li><p><strong>Model Types</strong>:</p><ul><li>Foundation models (general-purpose)</li><li>Specialized models (domain-specific)</li><li>Different generations and versions</li></ul></li><li><p><strong>Model Providers</strong>:</p><ul><li>Anthropic (Claude models)</li><li>Amazon (Titan models)</li><li>Additional providers may be added over time</li></ul></li></ol><h2 id="model-selection-interface" tabindex="-1">Model Selection Interface <a class="header-anchor" href="#model-selection-interface" aria-label="Permalink to &quot;Model Selection Interface&quot;">​</a></h2><h3 id="model-cards" tabindex="-1">Model Cards <a class="header-anchor" href="#model-cards" aria-label="Permalink to &quot;Model Cards&quot;">​</a></h3><p>Each available model is displayed as a card with comprehensive information:</p><ol><li><p><strong>Visual Elements</strong>:</p><ul><li>Provider logo (Anthropic, Amazon, etc.)</li><li>Provider name</li><li>Model name</li><li>Status badges and tags</li></ul></li><li><p><strong>Card Layout</strong>:</p><ul><li>Provider information in the left column</li><li>Model details in the center</li><li>Activation toggle in the right column</li></ul></li></ol><h3 id="model-details" tabindex="-1">Model Details <a class="header-anchor" href="#model-details" aria-label="Permalink to &quot;Model Details&quot;">​</a></h3><p>Each model card displays key performance and specification information:</p><ol><li><p><strong>Basic Information</strong>:</p><ul><li><strong>Model Name</strong>: Full name of the model (e.g., &quot;Claude 3 Sonnet&quot;)</li><li><strong>Status Badge</strong>: Indicates special status like &quot;Preview&quot; or &quot;Beta&quot;</li><li><strong>Availability Tag</strong>: &quot;Not Available&quot; appears for models that cannot be enabled</li></ul></li><li><p><strong>Specifications</strong>:</p><ul><li><strong>Released</strong>: Publication or release date</li><li><strong>Max Tokens</strong>: Maximum context length the model can process</li><li><strong>Cost</strong>: Relative cost indicator using dollar signs ($ to $$$)</li><li><strong>Per Credit</strong>: Credit consumption per use, shown as a percentage</li></ul></li><li><p><strong>Expanded Information</strong>:</p><ul><li><strong>Description</strong>: Detailed explanation of model capabilities and use cases</li><li><strong>Categories</strong>: Tags indicating strengths or specializations of the model</li></ul></li></ol><h3 id="enabling-models" tabindex="-1">Enabling Models <a class="header-anchor" href="#enabling-models" aria-label="Permalink to &quot;Enabling Models&quot;">​</a></h3><p>To control which models are available to your organization:</p><ol><li><p>Toggle the switch on the right side of each model card:</p><ul><li><strong>ON</strong>: Model will be available for selection in Blueprints and AI Settings</li><li><strong>OFF</strong>: Model will not be available for selection</li></ul></li><li><p>Unavailable models:</p><ul><li>Appear with reduced opacity</li><li>Have disabled toggle switches</li><li>Show &quot;Not Available&quot; tags</li></ul></li></ol><h2 id="understanding-model-information" tabindex="-1">Understanding Model Information <a class="header-anchor" href="#understanding-model-information" aria-label="Permalink to &quot;Understanding Model Information&quot;">​</a></h2><h3 id="provider-information" tabindex="-1">Provider Information <a class="header-anchor" href="#provider-information" aria-label="Permalink to &quot;Provider Information&quot;">​</a></h3><p>The model card identifies the AI provider:</p><ol><li><strong>Logo</strong>: Visual identifier for the model provider</li><li><strong>Make</strong>: Text name of the provider (e.g., &quot;Anthropic&quot; or &quot;Amazon&quot;)</li><li>This helps distinguish between different AI ecosystems</li></ol><h3 id="model-specifications" tabindex="-1">Model Specifications <a class="header-anchor" href="#model-specifications" aria-label="Permalink to &quot;Model Specifications&quot;">​</a></h3><p>Technical details help understand model capabilities:</p><ol><li><p><strong>Max Tokens</strong>:</p><ul><li>Measures context capacity in tokens (roughly 4 characters per token)</li><li>Larger numbers indicate ability to process longer content</li><li>Range typically from 8K to 200K tokens</li><li>Important for applications needing long context</li></ul></li><li><p><strong>Release Date</strong>:</p><ul><li>When the model version was released</li><li>Newer models generally have improved capabilities</li><li>Helps track model freshness and update cycles</li></ul></li></ol><h3 id="cost-information" tabindex="-1">Cost Information <a class="header-anchor" href="#cost-information" aria-label="Permalink to &quot;Cost Information&quot;">​</a></h3><p>Two cost indicators help with budget planning:</p><ol><li><p><strong>Dollar Signs</strong>:</p><ul><li>Relative cost indicator ($, $$, $$$, etc.)</li><li>More signs indicate higher per-token costs</li><li>Helps with quick cost comparisons</li></ul></li><li><p><strong>Credit Percentage</strong>:</p><ul><li>Platform-specific consumption metric</li><li>Displayed as a percentage (e.g., &quot;20%&quot;)</li><li>Higher percentages consume more credits per use</li><li>Important for budget allocation and monitoring</li></ul></li></ol><h3 id="status-indicators" tabindex="-1">Status Indicators <a class="header-anchor" href="#status-indicators" aria-label="Permalink to &quot;Status Indicators&quot;">​</a></h3><p>Status badges provide important availability information:</p><ol><li><p><strong>Not Available</strong>:</p><ul><li>Model cannot be enabled currently</li><li>May be due to contractual limits, region restrictions, or other factors</li><li>These models are shown for informational purposes only</li></ul></li><li><p><strong>Preview/Beta</strong>:</p><ul><li>Model is in early access or testing phase</li><li>May have limitations or performance variations</li><li>Consider carefully before using in production environments</li></ul></li></ol><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>Category tags help identify model specialties:</p><ol><li><p><strong>Purpose-Based Categories</strong>:</p><ul><li>Content Creation</li><li>Code</li><li>Analysis</li><li>Reasoning</li></ul></li><li><p><strong>Characteristic-Based Categories</strong>:</p><ul><li>Fast</li><li>Efficient</li><li>High Accuracy</li><li>Multilingual</li></ul></li></ol><p>These categories help match models to specific use cases and requirements.</p><h2 id="managing-model-visibility" tabindex="-1">Managing Model Visibility <a class="header-anchor" href="#managing-model-visibility" aria-label="Permalink to &quot;Managing Model Visibility&quot;">​</a></h2><h3 id="expand-collapse-features" tabindex="-1">Expand/Collapse Features <a class="header-anchor" href="#expand-collapse-features" aria-label="Permalink to &quot;Expand/Collapse Features&quot;">​</a></h3><p>To manage information density in the interface:</p><ol><li><p><strong>Show More</strong> Link:</p><ul><li>Click to expand individual model cards</li><li>Reveals description and category tags</li><li>Helps focus on models of interest</li></ul></li><li><p><strong>Expand All/Collapse All</strong>:</p><ul><li>Button in the top-right corner</li><li>&quot;Expand All&quot;: Shows detailed information for all models</li><li>&quot;Collapse All&quot;: Hides detailed information for all models</li><li>Useful when comparing multiple models</li></ul></li></ol><h2 id="model-selection-strategy" tabindex="-1">Model Selection Strategy <a class="header-anchor" href="#model-selection-strategy" aria-label="Permalink to &quot;Model Selection Strategy&quot;">​</a></h2><h3 id="use-case-considerations" tabindex="-1">Use Case Considerations <a class="header-anchor" href="#use-case-considerations" aria-label="Permalink to &quot;Use Case Considerations&quot;">​</a></h3><p>Different models excel at different tasks:</p><ol><li><p><strong>General Assistant Tasks</strong>:</p><ul><li>Choose balanced models like &quot;Sonnet&quot;</li><li>Good for varied questions and tasks</li><li>Middle-tier cost and performance</li></ul></li><li><p><strong>Content Creation</strong>:</p><ul><li>Choose models with strong writing capabilities</li><li>May have higher costs but produce better content</li><li>Look for &quot;Content Creation&quot; category tag</li></ul></li><li><p><strong>Technical and Code Applications</strong>:</p><ul><li>Choose models with code capabilities</li><li>Look for &quot;Code&quot; category tag</li><li>Consider models with higher accuracy ratings</li></ul></li></ol><h3 id="cost-management" tabindex="-1">Cost Management <a class="header-anchor" href="#cost-management" aria-label="Permalink to &quot;Cost Management&quot;">​</a></h3><p>Balance capabilities with budget constraints:</p><ol><li><p><strong>Budget-Focused Approach</strong>:</p><ul><li>Enable fewer, more targeted models</li><li>Select models with lower cost indicators</li><li>Focus on models with lower credit percentages</li><li>Disable expensive models that aren&#39;t essential</li></ul></li><li><p><strong>Capability-Focused Approach</strong>:</p><ul><li>Enable multiple models with different strengths</li><li>Allow Blueprint creators to select appropriate models</li><li>Consider enabling at least one lower-cost option</li></ul></li></ol><h3 id="performance-requirements" tabindex="-1">Performance Requirements <a class="header-anchor" href="#performance-requirements" aria-label="Permalink to &quot;Performance Requirements&quot;">​</a></h3><p>Consider the types of content and response times needed:</p><ol><li><p><strong>Response Speed Priority</strong>:</p><ul><li>Enable models tagged as &quot;Fast&quot;</li><li>Generally smaller models have faster response times</li><li>Look for lower token capacities</li></ul></li><li><p><strong>Complex Task Priority</strong>:</p><ul><li>Enable models with higher capabilities</li><li>Look for &quot;Reasoning&quot; and &quot;Analysis&quot; categories</li><li>Consider models with larger token capacities</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For optimal AI model configuration:</p><ol><li><p><strong>Balanced Selection</strong>:</p><ul><li>Enable at least one model from each price tier</li><li>Include models with different strengths</li><li>Consider enabling both fast and powerful options</li></ul></li><li><p><strong>Regular Review</strong>:</p><ul><li>Periodically review which models are most used</li><li>Consider disabling models that are rarely selected</li><li>Stay informed about new model releases</li></ul></li><li><p><strong>Pilot Testing</strong>:</p><ul><li>When new models become available, enable for testing</li><li>Gather feedback from power users</li><li>Monitor performance and costs before wider deployment</li></ul></li><li><p><strong>Cost Monitoring</strong>:</p><ul><li>Track credit usage across different models</li><li>Consider restricting very expensive models if budget is a concern</li><li>Balance capabilities needed with financial constraints</li></ul></li><li><p><strong>Use Case Alignment</strong>:</p><ul><li>Enable models appropriate for your organization&#39;s needs</li><li>Consider your industry and typical AI usage patterns</li><li>Disable models that don&#39;t align with your use cases</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Model shows &quot;Not Available&quot; status</p><ul><li>This model may not be available in your region</li><li>Your subscription tier may not include this model</li><li>Check with your account representative for availability</li></ul><p><strong>Issue</strong>: Enabled models not appearing in Blueprints</p><ul><li>Refresh the Blueprints interface</li><li>Check if the user has proper permissions</li><li>Verify the Blueprint is compatible with the model</li></ul><p><strong>Issue</strong>: Cannot enable/disable models</p><ul><li>Verify you have administrator privileges</li><li>Some models may be required by the system and cannot be disabled</li><li>Try refreshing the page</li></ul><p><strong>Issue</strong>: Cost concerns after enabling models</p><ul><li>Enable fewer high-cost models</li><li>Implement usage policies through Blueprints</li><li>Consider creating cost-optimized Blueprints for common tasks</li></ul><p><strong>Issue</strong>: Model performance doesn&#39;t match expectations</p><ul><li>Different models have different strengths</li><li>Try alternative models for specific tasks</li><li>Check system instructions in Blueprints</li><li>Consider adjusting creativity and response settings</li></ul><hr><p>For additional assistance with AI model configuration, please contact your system administrator or platform support team.</p>',69)]))}const h=i(t,[["render",n]]);export{p as __pageData,h as default};
